func (q *Queries) ReleaseVoidedApplications(ctx context.Context, arg ReleaseVoidedApplicationsParams) error {
	_, err := q.db.Exec(ctx, releaseVoidedApplications, arg.Author, arg.SpaceID, arg.OperationID)
	return err
}
